package com.dreamcore.workspace;
import com.dreamcore.workspace.conversation.*;
import com.dreamcore.workspace.feedback.*;
import com.dreamcore.workspace.feedbackadjustment.*;
import com.dreamcore.workspace.identity.IdentityException;
import java.nio.file.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;
/** Actual Harness and HTTP callbacks, with an explicitly synthetic local model; no real provider. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.enabled=true","dreamcore.tasks.agent-mode=verification","dreamcore.tasks.initial-delay-ms=3600000","dreamcore.object-lifecycle.enabled=false","dreamcore.departure.worker-enabled=false"})
class FeedbackAdjustmentHarnessIT {
 @Autowired ConversationService conversations;@Autowired AgentTaskService agents;@Autowired FeedbackAdjustmentService adjustments;@Autowired JdbcTemplate db;@LocalServerPort int port;
 @Test void capturedContextRunsThroughHarnessWaitsResumesAndLateResultCannotRevivePurgedSource()throws Exception{
  UUID tenant=UUID.randomUUID(),owner=UUID.randomUUID(),space=UUID.randomUUID(),conversation=UUID.randomUUID(),source=UUID.randomUUID();db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,'not-a-login')",owner,owner+"@example.test","合成调整 Harness");db.update("INSERT INTO tenants(id,name) VALUES (?,'合成调整企业')",tenant);db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,'MEMBER')",tenant,owner);db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'本人空间','PERSONAL')",space,tenant,owner);db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'原始合成卡片')",conversation,tenant,space,owner);db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,revision,attempt,reply,execution_class,finished_at) VALUES (?,?,?,?,?,'合成源','AGENT','SUCCEEDED',3,1,'原始卡片确切内容','verification',now())",source,tenant,space,conversation,owner);
  Path root=Path.of("").toAbsolutePath();if(root.endsWith("api"))root=root.getParent().getParent();String token="synthetic-adjustment-012345678901234567890123";Process engine=new ProcessBuilder("node",root.resolve("engine/tests/fixtures/task-control-server.mjs").toString(),"http://127.0.0.1:"+port,token).redirectError(ProcessBuilder.Redirect.INHERIT).start();
  try(var pool=Executors.newSingleThreadExecutor();var lines=new BufferedReader(new InputStreamReader(engine.getInputStream()))){String endpoint=pool.submit(lines::readLine).get(5,TimeUnit.SECONDS);assertNotNull(endpoint);var runtime=new EngineTaskRuntime(endpoint,token,"verification",false);var target=new FeedbackService.Target("BRIEFING",source,3,1,"briefing-basic-v1",0);
   var sent=adjustments.send(owner,tenant,new FeedbackAdjustmentService.Send(UUID.randomUUID(),target,0,0,"请调整本卡。"+"具".repeat(1800)));var first=conversations.claim();assertEquals(sent.message().taskId(),first.id());assertTrue(first.prompt().length()>2000);assertTrue(first.prompt().contains("原始卡片确切内容"));var waiting=runtime.executeAgent(first.id(),first.token(),first.prompt(),()->agents.active(first));assertEquals("WAITING_INPUT",waiting.outcome());agents.finish(first,waiting);var view=adjustments.open(owner,tenant,target,0,20);assertEquals("请补充截止日期",view.items().getFirst().requiredInput());conversations.action(owner,tenant,sent.conversationId(),first.id(),UUID.randomUUID(),view.items().getFirst().taskRevision(),"RESUME","补充到周五");var second=conversations.claim();var result=runtime.executeAgent(second.id(),second.token(),second.prompt(),()->agents.active(second));assertEquals("COMPLETE",result.outcome());agents.finish(second,result);view=adjustments.open(owner,tenant,target,0,20);assertEquals("SUCCEEDED",view.items().getFirst().status());assertTrue(view.items().getFirst().reply().contains("依据补充完成"));assertEquals("补充到周五",view.items().getFirst().supplementalInput());assertEquals(2,conversations.attempts(owner,tenant,sent.conversationId(),first.id(),0,10).items().size());
   var later=adjustments.send(owner,tenant,new FeedbackAdjustmentService.Send(UUID.randomUUID(),target,1,1,"再核对本次表达"));var late=conversations.claim();assertEquals(later.message().taskId(),late.id());var lateResult=runtime.executeAgent(late.id(),late.token(),late.prompt(),()->agents.active(late));db.queryForList("SELECT scrub_lifecycle_object('TASK',?)",source);assertThrows(IdentityException.class,()->agents.finish(late,lateResult));assertNull(db.queryForObject("SELECT reply FROM conversation_tasks WHERE id=?",String.class,late.id()));assertEquals("{}",db.queryForObject("SELECT snapshot::text FROM feedback_adjustment_messages WHERE task_id=?",String.class,late.id()));
  }finally{engine.destroy();if(!engine.waitFor(3,TimeUnit.SECONDS))engine.destroyForcibly();db.update("UPDATE conversation_tasks SET status='CANCELLED' WHERE tenant_id=? AND status IN('QUEUED','RUNNING')",tenant);}
 }
}
